-- Queer Atlas: Gaborone, Botswana.
-- Researched 2026-08-28. Run country-botswana-qari-v1.sql first.
-- Only production-approved place/service types are used. No unverified sauna, cruise club or cruising area is inserted.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

do $qa_require_qari$
begin
  if not exists(select 1 from public.qa_qari_profiles where destination_key='country:botswana' and scope_type='country' and is_published=true) then
    raise exception 'Published QARI profile country:botswana is required before Gaborone can run.';
  end if;
end;
$qa_require_qari$;

with src as (
 select * from jsonb_to_recordset($qa_cities$
[
 {"slug":"gaborone","name":"Gaborone","title":"Queer Gaborone","country":"Botswana","country_code":"BW","latitude":-24.6282,"longitude":25.9231,"timezone":"Africa/Gaborone","vibe":"low-key, resilient and community-connected","local_mood":"Gaborone's queer life is discreet and network-led. LEGABIBO supplies the clearest permanent LGBTQ+ anchor, while nightlife happens in mixed venues whose audience and atmosphere change by event.","queer_status":"Consensual same-sex intimacy is legal and the offending Penal Code provisions were formally removed in 2026, but same-sex relationships lack legal recognition and lived acceptance remains uneven.","crowd_profile":"LGBTQI+ Batswana, activists, students, professionals, artists, visitors and allies meet through community services, private networks and selected mixed bars, clubs, restaurants and cafés.","introduction":"Gaborone should not be marketed with an invented gay district. Bull & Bush and Déjàvu have current queer-friendly signals but remain mixed venues; Park 27, Two Six Seven and Ola Tia are useful social options with broad crowds. LEGABIBO's Drop-In Centre is the dependable specialist resource. No active dedicated gay sauna, cruise club or public cruising area could be verified, and isolated cruising is not recommended.","guide_items":[{"title":"About","text":"The city's LGBTQ+ infrastructure is organisational rather than commercial, with LEGABIBO providing confidential health, counselling and community support."},{"title":"Districts","text":"The CBD and New CBD carry late nightlife and major hotels; Riverwalk, Extension 27, Broadhurst and Block 10 provide dispersed social options, so door-to-door transport matters."},{"title":"Safety","text":"Keep public affection context-aware, use a known taxi or driver after dark, protect app and phone privacy, and hold first app meetings in staffed public places. Avoid isolated cruising locations."},{"title":"Nightlife","text":"Check the operator's current post before leaving. Déjàvu and Bull & Bush are mixed rather than dedicated queer venues, and no permanent gay sauna or cruise club is verified."},{"title":"Cost","text":"Venue prices are moderate by international standards, but taxis between dispersed districts and secure late-night transport should be budgeted."}],"guide_sources":[{"label":"LEGABIBO services","url":"https://legabibo.org.bw/services"},{"label":"Botswana government legal update","url":"https://dailynews.gov.bw/news-detail/90873"},{"label":"UK Botswana safety advice","url":"https://www.gov.uk/foreign-travel-advice/botswana/safety-and-security"}],"safety_context":"Legal reform has materially improved the baseline, but it has not created uniform social acceptance. Use verified mixed venues deliberately, organise direct transport, minimise unnecessary disclosure, and contact LEGABIBO for current community-grounded guidance. No cruising location is published because none met the evidence and safety threshold.","qari_key":"country:botswana"}
]
$qa_cities$) c(slug text,name text,title text,country text,country_code text,latitude double precision,longitude double precision,timezone text,vibe text,local_mood text,queer_status text,crowd_profile text,introduction text,guide_items jsonb,guide_sources jsonb,safety_context text,qari_key text)
)
insert into public.qa_cities(slug,name,title,country,country_code,latitude,longitude,map_confirmed,timezone,vibe,local_mood,queer_status,crowd_profile,introduction,guide_items,guide_sources,guide_checked_at,safety_context,qari_destination_key,qari_score,qari_summary,qari_confidence,status,updated_at)
select c.slug,c.name,c.title,c.country,c.country_code,c.latitude,c.longitude,true,c.timezone,c.vibe,c.local_mood,c.queer_status,c.crowd_profile,c.introduction,c.guide_items,c.guide_sources,date '2026-08-28',c.safety_context,q.destination_key,q.qari_score,q.summary,q.confidence,'published',timezone('utc',now()) from src c cross join lateral(select destination_key,qari_score,summary,confidence from public.qa_qari_profiles where destination_key=c.qari_key and scope_type='country' and is_published=true order by reviewed_at desc nulls last limit 1) q
on conflict(slug) do update set name=excluded.name,title=excluded.title,country=excluded.country,country_code=excluded.country_code,latitude=excluded.latitude,longitude=excluded.longitude,map_confirmed=true,timezone=excluded.timezone,vibe=excluded.vibe,local_mood=excluded.local_mood,queer_status=excluded.queer_status,crowd_profile=excluded.crowd_profile,introduction=excluded.introduction,guide_items=excluded.guide_items,guide_sources=excluded.guide_sources,guide_checked_at=excluded.guide_checked_at,safety_context=excluded.safety_context,qari_destination_key=excluded.qari_destination_key,qari_score=excluded.qari_score,qari_summary=excluded.qari_summary,qari_confidence=excluded.qari_confidence,status='published',updated_at=excluded.updated_at;

with raw_places as (
 select * from jsonb_to_recordset($qa_places$
[
 {"name":"Bull & Bush","city":"gaborone","type":"bar","description":"A long-running Broadhurst garden pub where big trees, live bands, sport and a broad local crowd make the evening feel more like a social compound than a polished cocktail room.","hours":"Monday-Thursday 12:00-23:00; Friday 12:00-00:00; Saturday 11:00-00:00; Sunday 12:00-17:00.","link":"https://www.bullbush.com/","location":"Legolo Road, Broadhurst, Gaborone, Botswana","lat":-24.63992,"lng":25.91044,"vibe":"leafy mixed garden pub with live music and easy group energy","q":"Friday events and major matches can crowd the garden; use direct transport rather than walking dark surrounding roads.","best":"Early evening suits food and conversation; choose a named live-music night for the fullest atmosphere.","crowd":"Local professionals, musicians, sports audiences, expatriates, LGBTQ+ guests and mixed friend groups.","dress":"Relaxed pub casual; weather-ready layers for the garden.","staff":"Current queer-travel evidence gives an LGBTQ-friendly signal, but Bull & Bush is a mixed venue and no queer ownership or every-night safe-space claim is made.","safety":"Arrange a taxi or known driver for departure after dark, watch drinks in crowded events and keep public affection calibrated to the mixed room.","hours_source":"https://www.restaurants10.com/BW/Gaborone/669634326393958/Bull-%26-Bush","sources":["https://www.bullbush.com/","https://www.restaurants10.com/BW/Gaborone/669634326393958/Bull-%26-Bush","https://www.gayout.com/africa/botswana/gaborone"]},
 {"name":"Déjàvu Lounge CBD","city":"gaborone","type":"club","description":"A glossy late club high in Gaborone's CBD rhythm, built around DJs, bottle-service energy and a dance floor that wakes well after dinner.","hours":"Monday-Tuesday closed; Wednesday 22:00-04:00; Thursday 22:00-06:00; Friday-Saturday 23:00-06:00; Sunday 22:00-06:00.","link":"https://www.facebook.com/DejavuLoungeCBD/","location":"iTowers, New CBD, Gaborone, Botswana","lat":-24.64753,"lng":25.90584,"vibe":"high-gloss mixed late club with DJ-driven CBD momentum","q":"Peak entry comes after midnight and the late finish requires transport booked before phones or batteries become unreliable.","best":"Friday and Saturday deliver the largest dance crowd; arrive earlier if avoiding bottle-service congestion matters.","crowd":"Young professionals, students, nightlife regulars, LGBTQ+ guests, visitors and mixed groups.","dress":"Fashion-forward clubwear; bring identification and check the event post for door rules.","staff":"Current local nightlife recommendations and queer-travel evidence support a queer-friendly mixed classification, not a dedicated gay-club label.","safety":"This is a high-alcohol late club. Keep your drink, phone and companions in view; use a pre-arranged ride and do not move an app meeting to an isolated location.","hours_source":"https://www.findglocal.com/BW/Gaborone/1382336911829571/D%C3%A9j%C3%A0vu-Lounge-CBD","sources":["https://www.facebook.com/DejavuLoungeCBD/","https://www.findglocal.com/BW/Gaborone/1382336911829571/D%C3%A9j%C3%A0vu-Lounge-CBD","https://www.reddit.com/r/Botswana/comments/1spvo2x/recommendations/"]},
 {"name":"Park 27","city":"gaborone","type":"restaurant","description":"A garden restaurant inside Extension 27's green pocket, pairing all-day plates and cocktails with lawns, artful landscaping and the feeling of a city picnic after sunset.","hours":"Monday-Sunday 08:00-23:45.","link":"https://www.park27bw.com/","location":"Plot 7150, Extension 27, Gaborone, Botswana","lat":-24.63166,"lng":25.92869,"vibe":"lush all-day garden dining with relaxed social polish","q":"Weekend meals and celebrations can fill popular tables; reserve for a group or event date.","best":"Late afternoon moves naturally from garden lunch into cocktails without committing to a club.","crowd":"Professionals, families, couples, creatives, LGBTQ+ diners and mixed celebration groups.","dress":"Polished casual with practical shoes for garden surfaces.","staff":"The venue is included as a current broad-audience social option, not described as gay-owned or a dedicated queer space.","safety":"The garden setting becomes quieter at night; leave through the staffed entrance and use direct transport rather than walking an unfamiliar route.","hours_source":"https://www.park27bw.com/","sources":["https://www.park27bw.com/","https://www.instagram.com/park27gaborone/"]},
 {"name":"Two Six Seven Kitchen + Bar","city":"gaborone","type":"restaurant","description":"A Riverwalk kitchen-bar with bold Botswana-rooted cooking, cocktails and a contemporary dining room that works equally well for a first public meet or a long group dinner.","hours":"Monday closed; Tuesday-Thursday 11:00-22:30; Friday-Saturday 11:00-23:00; Sunday 11:00-17:00.","link":"https://www.facebook.com/twosixsevenbw/","location":"Plot 64861, Riverwalk, Gaborone, Botswana","lat":-24.67720,"lng":25.93335,"vibe":"confident contemporary local dining with a sociable bar edge","q":"Dinner and event periods reward booking; mall access is simpler than an improvised late arrival.","best":"Use an early dinner for a discreet first meeting or Friday evening for the livelier bar atmosphere.","crowd":"Local food lovers, professionals, couples, visitors, LGBTQ+ diners and mixed groups.","dress":"Smart-casual dining clothes.","staff":"Included as a current, public, staffed mixed venue suitable for queer travellers; no exclusive LGBTQ+ identity is claimed.","safety":"A staffed restaurant is preferable to an isolated first app meeting. Share plans with a trusted person and arrange the return ride before closing.","hours_source":"https://www.africabizinfo.com/BW/two-six-seven-restuarant-bar-391-0085","sources":["https://www.facebook.com/twosixsevenbw/","https://www.africabizinfo.com/BW/two-six-seven-restuarant-bar-391-0085"]},
 {"name":"Ola Tia Coffee and Cream","city":"gaborone","type":"cafe","description":"A bright Remmogo Crossing café where excellent coffee and cake share the calendar with salsa, open-mic evenings, book clubs, live music and playful social formats.","hours":"Monday-Sunday 08:30-18:00.","link":"https://www.instagram.com/olatiacafe/","location":"Remmogo Crossing Shopping Centre, Airport Junction, Block 10, Gaborone, Botswana","lat":-24.56650,"lng":25.97410,"vibe":"creative daytime café with community-minded events and soft social energy","q":"Named events may need reservations; ordinary daytime service is calmer.","best":"Daytime is ideal for a first meeting; follow the current programme for open mic, salsa or book-club energy.","crowd":"Coffee regulars, creatives, students, families, couples, LGBTQ+ visitors and event participants.","dress":"Easy daytime casual.","staff":"The evidence supports an active broad community café, not a dedicated queer identity; its public staffed setting makes it a useful low-pressure meeting option.","safety":"The mall setting and daylight hours lower meeting risk, but normal app privacy and independent transport still matter.","hours_source":"https://www.gaboroneexplorer.com/explore/10-cafes-in-gaborone","sources":["https://www.instagram.com/olatiacafe/","https://www.gaboroneexplorer.com/explore/10-cafes-in-gaborone","https://lephutshi.com/listing/ola-tia-coffee-and-cream-airport-junction-gaborone/"]}
]
$qa_places$) p(name text,city text,type text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,q text,best text,crowd text,dress text,staff text,safety text,hours_source text,sources jsonb)
), places as (
 select p.*,jsonb_build_object('queue_wait',q,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,'staff_inclusivity',staff,'safety_note',safety,'hours_source_url',hours_source,'hours_checked_at','2026-08-28','source_urls',sources,'research_status','current_operator_or_current_directory_plus_identity_context','updated_at','2026-08-28T00:00:00Z') intel from raw_places p
), updated as (
 update public.places t set type=p.type,description=p.description,hours=p.hours,link=p.link,location=p.location,lat=p.lat,lng=p.lng,vibe=p.vibe,vibe_tags=array[]::text[],venue_intel=coalesce(t.venue_intel,'{}'::jsonb)||p.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from places p where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)) returning t.id
)
insert into public.places(name,city,type,description,hours,link,location,lat,lng,vibe,vibe_tags,venue_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,description,hours,link,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from places p where not exists(select 1 from public.places t where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)));

with raw_services as (
 select * from jsonb_to_recordset($qa_services$
[
 {"name":"LEGABIBO Gaborone Drop-In Centre","city":"gaborone","type":"wellness","provider":"LEGABIBO","contact":"+267 316 7425; WhatsApp +267 71 340 794; info@legabibo.org.bw","booking":"https://legabibo.org.bw/services","description":"Botswana's established LGBTQ+ organisation provides confidential HIV testing and counselling, ART linkage and literacy, PrEP referral, condoms and lubricants, mental-health support and community-strengthening services from its Gaborone Drop-In Centre.","hours":"Monday-Thursday 08:00-17:00; Friday 08:00-13:00; Saturday-Sunday closed. Emergency-support availability is separate and must be confirmed by phone.","link":"https://legabibo.org.bw/services","location":"Plot 111, Unit 7, Gaborone International Commerce Park, Gaborone, Botswana","lat":-24.69350,"lng":25.88750,"vibe":"confidential specialist LGBTQ+ health, counselling and community support","lead":"Call or WhatsApp before travel to confirm the requested service, clinician or counsellor and whether an appointment is needed.","best":"Contact during published weekday hours; emergencies use the separately listed support route.","crowd":"LGBTQI+ people, partners, parents and other marginalised communities seeking affirming health or psychosocial support.","prep":"Ask about identification, cost, confidentiality, test window, result timing, accessibility and current commodity availability.","incl":"LEGABIBO explicitly serves and is led around Botswana's LGBTIQ+ communities; this is the city's strongest verified specialist inclusion signal.","safety":"Use the exact official address and contact, preserve the privacy of other visitors, and do not confuse general office hours with 24/7 emergency availability.","sources":["https://legabibo.org.bw/services","https://legabibo.org.bw/"]}
]
$qa_services$) s(name text,city text,type text,provider text,contact text,booking text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,lead text,best text,crowd text,prep text,incl text,safety text,sources jsonb)
), services as (
 select s.*,jsonb_build_object('booking_lead_time',lead,'best_time',best,'client_mix',crowd,'preparation',prep,'provider_inclusivity',incl,'safety_note',safety,'hours_source_url','https://legabibo.org.bw/services','hours_checked_at','2026-08-28','source_urls',sources,'research_status','current_first_party_service_source','updated_at','2026-08-28T00:00:00Z') intel from raw_services s
), updated as (
 update public.services t set type=s.type,provider_name=s.provider,contact=s.contact,booking_link=s.booking,description=s.description,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],source='LEGABIBO official services; checked 2026-08-28',"lastChecked"=date '2026-08-28',verified=true,service_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from services s where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)) returning t.id
)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,vibe,vibe_tags,source,"lastChecked",verified,service_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,provider,contact,booking,description,hours,link,location,lat,lng,vibe,array[]::text[],'LEGABIBO official services; checked 2026-08-28',date '2026-08-28',true,intel,true,'approved',timezone('utc',now()) from services s where not exists(select 1 from public.services t where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)));

select public.qa_refresh_city_seo_status('gaborone') where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select type,count(*) from public.places where lower(trim(city))='gaborone' group by type order by type;
select name,type,hours,venue_intel->>'hours_source_url' as hours_source from public.places where lower(trim(city))='gaborone' order by type,name;
select slug,country,qari_destination_key,qari_score,status from public.qa_cities where slug='gaborone';
